const chrome={"header":"\n<a class=\"skip\" href=\"/#shop\">Skip to products</a><header><nav class=\"nav wrap\" aria-label=\"Main navigation\"><a class=\"logo\" href=\"/#top\" aria-label=\"Elvarins home\"><img src=\"/logo.svg\" width=\"38\" height=\"38\" alt=\"\">Elvarins<b>.</b></a><div class=\"navlinks\"><a href=\"/#shop\">Toys &amp; Collectibles</a><a href=\"/#collections\">Departments</a><a href=\"/#about\">About</a><a href=\"/#contact\">Contact</a></div><a class=\"navsupport\" href=\"mailto:sales@elvarins.com\">Customer support \u2197</a><button class=\"menu-button\" id=\"navtoggle\" aria-label=\"Open menu\" aria-expanded=\"false\" aria-controls=\"mobilemenu\">Menu</button></nav><div id=\"mobilemenu\" hidden><a href=\"/#shop\">Toys &amp; Collectibles</a><a href=\"/#collections\">Departments</a><a href=\"/#about\">About Elvarins</a><a href=\"/#contact\">Customer support</a></div></header>\n<div class=\"announcement\">U.S. shipping <span aria-hidden=\"true\"> \u00b7 </span> 1\u20132 business day order processing <span aria-hidden=\"true\"> \u00b7 </span> <a href=\"/#shipping\">Shipping details</a></div>\n","footer":"<footer><div class=\"wrap\"><div class=\"footer-grid\"><div><a class=\"logo\" href=\"/#top\"><img src=\"/logo.svg\" width=\"32\" height=\"32\" alt=\"\">Elvarins<b>.</b></a><p>Operated by Shahabaz Global Trading LLC<br>30 N Gould St STE R, Sheridan, WY 82801<br>Registered business address</p></div><div><h3>Explore</h3><a href=\"/#shop\">Toys &amp; Collectibles</a><a href=\"/#pets\">Pet Supplies</a><a href=\"/#health\">Health &amp; Household</a><a href=\"/#about\">About Elvarins</a></div><div><h3>Customer care</h3><a href=\"/#shipping\">Shipping &amp; Processing</a><a href=\"/#returns\">Returns &amp; Refunds</a><a href=\"/#contact\">Contact Us</a><a href=\"/#privacy\">Privacy</a></div></div><div class=\"footer-bottom\"><span>\u00a9 2026 Shahabaz Global Trading LLC. All rights reserved.</span><span>U.S. retail \u00b7 Prices in USD</span></div></div></footer>\n"};
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const json=value=>JSON.stringify(value).replace(/</g,'\\u003c');
function metadata(title,description,path,image,structured){return `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escape(title)} | Elvarins</title><meta name="description" content="${escape(description)}"><meta name="robots" content="index,follow"><link rel="canonical" href="https://elvarins.com${escape(path)}"><meta property="og:type" content="product"><meta property="og:title" content="${escape(title)} | Elvarins"><meta property="og:description" content="${escape(description)}"><meta property="og:url" content="https://elvarins.com${escape(path)}"><meta property="og:image" content="${escape(image)}"><meta name="twitter:card" content="summary_large_image"><meta name="theme-color" content="#15264a"><link rel="icon" type="image/png" sizes="96x96" href="/favicon.png"><link rel="icon" type="image/svg+xml" href="/logo.svg"><link rel="stylesheet" href="/style.css"><link rel="preconnect" href="https://media.entertainmentearth.com"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet"><script type="application/ld+json">${json(structured)}</script></head><body>`;}
function card(p){return `<article class="product-card"><a class="product-photo" href="${escape(p.url)}"><img src="${escape(p.image)}" alt="${escape(p.title)}" width="500" height="500" loading="lazy" decoding="async" referrerpolicy="no-referrer"></a><div class="product-copy"><span class="brand">${escape(p.brand)}</span><h3><a href="${escape(p.url)}">${escape(p.title)}</a></h3><span class="unit">One retail item</span><div class="product-bottom"><span class="price">$${p.price.toFixed(2)} <small>USD</small></span><a class="product-action" href="${escape(p.url)}">View item ↗</a></div></div></article>`;}
export function renderProduct(p){
 const collection=collections.find(c=>c.slug===p.collection),related=products.filter(x=>x.collection===p.collection&&x.sku!==p.sku).slice(0,3);
 const breadcrumb={'@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:'Home',item:'https://elvarins.com/'},{'@type':'ListItem',position:2,name:collection.name,item:'https://elvarins.com/collections/'+collection.slug},{'@type':'ListItem',position:3,name:p.title,item:'https://elvarins.com'+p.url}]};
 const structured={'@context':'https://schema.org','@graph':[{'@type':'Product','@id':'https://elvarins.com'+p.url+'#product',name:p.title,sku:p.sku,description:p.description,image:p.image,url:'https://elvarins.com'+p.url,category:p.productType,brand:{'@type':'Brand',name:p.brand}},breadcrumb]};
 return metadata(p.title,p.description,p.url,p.image,structured)+chrome.header.replace('class="skip" href="/#shop"','class="skip" href="#product-main"')+`<main class="product-page" id="product-main"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a><span aria-hidden="true">/</span><a href="/collections/${escape(collection.slug)}">${escape(collection.name)}</a><span aria-hidden="true">/</span><span>${escape(p.sku)}</span></nav><div class="detail-grid"><div class="detail-photo"><div><img src="${escape(p.image)}" alt="${escape(p.title)}" width="500" height="500" fetchpriority="high" referrerpolicy="no-referrer"><a class="zoom-link" href="${escape(p.image)}" target="_blank" rel="noopener noreferrer">Open full-size photo ↗</a></div></div><div class="detail-copy"><span class="brand">${escape(p.brand)}</span><h1>${escape(p.title)}</h1><span class="price">$${p.price.toFixed(2)} <small>USD</small></span><p class="description">${escape(p.description)}</p><dl><dt>Brand</dt><dd>${escape(p.brand)}</dd><dt>Item number</dt><dd>${escape(p.sku)}</dd><dt>Product type</dt><dd>${escape(p.productType)}</dd>${p.size?`<dt>Item size</dt><dd>${escape(p.size)}</dd>`:''}<dt>Selling unit</dt><dd>One original retail package</dd></dl><form id="shipping-form" class="shipping-form"><label for="shipping-qty">Quantity</label><input id="shipping-qty" type="number" min="1" max="20" value="1" required><p id="item-subtotal"></p><label for="shipping-zip">U.S. delivery ZIP code</label><input id="shipping-zip" inputmode="numeric" autocomplete="postal-code" pattern="[0-9]{5}(-[0-9]{4})?" maxlength="10" placeholder="e.g. 10001" required><button class="btn btn-primary" type="submit" id="shipping-submit">Check shipping</button><p id="shipping-result" role="status" aria-live="polite">Shipping is confirmed before purchase. It is not included in the item price.</p></form><a id="detail-inquiry" class="btn btn-primary" href="mailto:sales@elvarins.com?subject=${encodeURIComponent('Purchase inquiry — '+p.sku)}">Request purchase details →</a><p class="detail-note">Contact us to confirm availability, shipping and any applicable taxes before purchase. Your inquiry does not place an order. Online checkout is not yet enabled.</p><div class="detail-help"><a href="/#shipping">U.S. shipping · 1–2 business day processing</a><a href="/#returns">30-day return policy · conditions apply</a></div></div></div><section class="related-products" aria-labelledby="related-title"><h2 id="related-title">More from ${escape(collection.name)}</h2><div class="product-grid">${related.map(card).join('')}</div><p><a href="/collections/${escape(collection.slug)}">Explore the collection →</a></p></section></main>`+chrome.footer+`<script id="product-data" type="application/json">${json(p)}</script><script src="/product.js" defer></script></body></html>`;
}
export function renderCollection(slug,homepage){
 const c=collections.find(c=>c.slug===slug);if(!c)return null;const subset=products.filter(p=>p.collection===slug);
 let page=homepage.replace(/<title>.*?<\/title>/,`<title>${escape(c.name)} Toys &amp; Collectibles | Elvarins</title>`).replace(/(<meta name="description" content=")[^"]*(">)/,`$1${escape(c.description)}$2`).replace(/(<link rel="canonical" href=")[^"]*(">)/,`$1https://elvarins.com/collections/${slug}$2`).replace(/(<meta property="og:title" content=")[^"]*(">)/,`$1${escape(c.name)} | Elvarins$2`).replace(/(<meta property="og:description" content=")[^"]*(">)/,`$1${escape(c.description)}$2`).replace(/(<meta property="og:url" content=")[^"]*(">)/,`$1https://elvarins.com/collections/${slug}$2`);
 page=page.replace(/<section class="hero">[\s\S]*?<\/section>/,`<section class="collection-hero"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a><span aria-hidden="true">/</span><span>${escape(c.name)}</span></nav><span class="eyebrow">Elvarins · Toys &amp; collectibles</span><h1>${escape(c.name)}</h1><p>${escape(c.description)}</p></section>`);
 page=page.replace(/<article class="product-card" data-sku="([^"]+)">[\s\S]*?<\/article>/g,(all,sku)=>subset.some(p=>p.sku===sku)?all:'');
 page=page.replace(/<script id="catalog-data" type="application\/json">[\s\S]*?<\/script>/,`<script id="catalog-data" type="application/json">${json(subset)}</script>`);
 page=page.replace(/<script type="application\/ld\+json">[\s\S]*?<\/script>/,`<script type="application/ld+json">${json({'@context':'https://schema.org','@type':'CollectionPage',name:c.name,description:c.description,url:'https://elvarins.com/collections/'+slug,mainEntity:{'@type':'ItemList',itemListElement:subset.map((p,i)=>({'@type':'ListItem',position:i+1,name:p.title,url:'https://elvarins.com'+p.url}))}})}</script>`);
 page=page.replace('href="/collections/'+slug+'"','aria-current="page" href="/collections/'+slug+'"');
 page=page.replace(/href="#(top|collections|about|contact|shipping|returns|pets|health|privacy)"/g,'href="/#$1"');
 return page;
}
